const agentOutput = ($input.first().json.output || '').trim();

const opPatterns = [
  { type: 'upload',   re: /upload|creat|wrote|saved|added/i },
  { type: 'download', re: /download|retriev|read|fetch/i },
  { type: 'list',     re: /presales list|list operation|create.*presale|update.*presale|log.*opportunit|persist.*presale|saved.*presale|item[Ii][Dd]|found.*presale|retriev.*all|get all presale|top.*presale|all presale/i },
];
let operation = 'unknown';
for (const p of opPatterns) {
  if (p.re.test(agentOutput)) { operation = p.type; break; }
}

const webUrlMatch = agentOutput.match(/https?:\/\/[^\s"'<>]*sharepoint[^\s"'<>]*/i);
const webUrl = webUrlMatch ? webUrlMatch[0].replace(/[.,;)]+$/, '') : null;

const itemIdMatch = agentOutput.match(/item[Ii][Dd][:\s]+(\d+)/);
const itemId = itemIdMatch ? itemIdMatch[1] : null;

// Only throw if the agent explicitly reports a tool-level failure — not for general error words in its own reasoning
const isToolError = /Upload failed|Download failed|List operation failed|error:\s+(siteUrl|folderPath|fileName|fileContent|operation|fields|itemId|401|403|404|500)/i.test(agentOutput);

if (isToolError) {
  return [{
    json: {
      success: false,
      operation,
      webUrl,
      itemId,
      error: agentOutput,
      agentMessage: agentOutput,
    }
  }];
}

return [{
  json: {
    success: true,
    operation,
    webUrl,
    itemId,
    agentMessage: agentOutput,
  }
}];
